package com.dndmaster.combatmap.application.view;
import com.dndmaster.combatmap.domain.*; import java.util.*;
public record PlayerCombatMapView(MapId mapId,GridSpec grid,List<CombatToken> tokens,Set<GridPosition> obstacles,List<Door> doors,List<MapLayer> layers,Set<GridPosition> current,Set<GridPosition> explored,Set<TokenId> lastSeenTokens,long version){public PlayerCombatMapView{tokens=List.copyOf(tokens);obstacles=Set.copyOf(obstacles);doors=List.copyOf(doors);layers=List.copyOf(layers);current=Set.copyOf(current);explored=Set.copyOf(explored);lastSeenTokens=Set.copyOf(lastSeenTokens);if(tokens.stream().anyMatch(t->t.discovery()==TokenDiscovery.HIDDEN))throw new IllegalArgumentException("player view contains hidden token");if(layers.stream().anyMatch(l->l.visibility()!=LayerVisibility.PLAYER_VISIBLE))throw new IllegalArgumentException("player view contains AI_ONLY layer");if(!explored.containsAll(current)||version<0)throw new IllegalArgumentException("invalid player visibility");}}
